    {
      "from_task": "deploy-promtail",
      "to_task": "configure-grafana",
      "kind": "hard"
    },
    {
      "from_task": "configure-grafana",
      "to_task": "set-log-retention",
      "kind": "hard"
    }
  ],
  "branches": []
